CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY,name TEXT,url TEXT,license TEXT,access TEXT,retrieved TEXT,original_id TEXT,raw TEXT);
CREATE TABLE IF NOT EXISTS markers(id TEXT PRIMARY KEY,person TEXT REFERENCES people(id),kind TEXT,status TEXT,reason TEXT,source TEXT,UNIQUE(person,kind,reason));
CREATE INDEX IF NOT EXISTS markers_kind ON markers(kind,person);
CREATE TABLE IF NOT EXISTS duplicate_reviews(a TEXT,b TEXT,state TEXT,reason TEXT,PRIMARY KEY(a,b));
CREATE TABLE IF NOT EXISTS merge_history(id TEXT PRIMARY KEY,created TEXT,keep_id TEXT,removed_id TEXT,snapshot BLOB,after_digest TEXT,undone INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS shared_matches(owner TEXT REFERENCES people(id),a TEXT REFERENCES people(id),b TEXT REFERENCES people(id),source TEXT,PRIMARY KEY(owner,a,b));
CREATE TABLE IF NOT EXISTS branches(owner TEXT REFERENCES people(id),person TEXT REFERENCES people(id),branch TEXT,evidence TEXT,PRIMARY KEY(owner,person));
CREATE TABLE IF NOT EXISTS famous(person TEXT PRIMARY KEY REFERENCES people(id),category TEXT,source TEXT);
CREATE TABLE IF NOT EXISTS findings(id TEXT PRIMARY KEY,task TEXT,person TEXT REFERENCES people(id),provider TEXT,external_id TEXT,title TEXT,payload TEXT,source TEXT,status TEXT DEFAULT 'proposed');
CREATE TABLE IF NOT EXISTS ancient_samples(id TEXT PRIMARY KEY,dataset TEXT,version TEXT,sample_id TEXT,site TEXT,country TEXT,period TEXT,age TEXT,sex TEXT,haplogroup TEXT,build TEXT,license TEXT,citation TEXT,raw TEXT,UNIQUE(dataset,version,sample_id));
CREATE INDEX IF NOT EXISTS ancient_country ON ancient_samples(country,period);
CREATE TABLE IF NOT EXISTS ancient_comparisons(id TEXT PRIMARY KEY,sample TEXT REFERENCES ancient_samples(id),person TEXT REFERENCES people(id),result TEXT,created TEXT);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,person TEXT REFERENCES people(id),kind TEXT,date TEXT,place TEXT,lat REAL,lon REAL,citation TEXT);
CREATE INDEX IF NOT EXISTS events_person ON events(person);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY,message TEXT,person TEXT,created TEXT);
CREATE TABLE IF NOT EXISTS import_history(id TEXT PRIMARY KEY,kind TEXT,source TEXT,size INTEGER,status TEXT,result TEXT,created TEXT);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT);
CREATE INDEX IF NOT EXISTS people_place ON people(place);
CREATE INDEX IF NOT EXISTS people_birth ON people(birth);
CREATE INDEX IF NOT EXISTS identities_person ON identities(person);
INSERT OR IGNORE INTO migrations VALUES(2);
